        grid = lambda META: (triton.cdiv(C, META["BLOCK_N"]), B)

        sum_reduce_kernel[grid](
            x,
            output,
            B,
            R,
            C,
            x.stride(0),
            x.stride(1),
            x.stride(2),
            output.stride(0),
            output.stride(2),
        )

        return output
